        return SDB_E_INVALID_ARGUMENT;
    }
    status = sdb_transaction_begin(database, &txn);
    if (status != SDB_OK) {
        return status;
    }
    for (index = 0U; index < op_count && op == SDB_OK; ++index) {
        const sdb_batch_op *entry = &ops[index];
