    st = sdb_kv_count_prefix(db, (const uint8_t *)ns, strlen(ns),
                             prefix, prefix_size, &count);
    sdb_status close_st = sdb_database_close(db);
    if (st != SDB_OK) {
        return fail("count", st);
    }
    if (close_st != SDB_OK) {
        return fail("count (close)", close_st);
