    assert(sdb_kv_compare_and_swap(db, NS, NS_SIZE, (const uint8_t *)"cas", 3U,
                                   (const uint8_t *)"v1", 2U,
                                   (const uint8_t *)"v3", 2U) == SDB_OK);
