$writer = "C:\shibadb\build-msvc\crash_writer.exe"
$dir = "C:\shibadb\build-msvc\_crashprod"
$db = "$dir\prod.shiba"; $pw = "prod-secret-key-2026"
$out = "$dir\out.txt"; $err = "$dir\err.txt"
$rounds = 24; $kills = 0; $corrupt = 0; $lost = 0; $maxCounter = 0; $prevCounter = 0
for ($r = 1; $r -le $rounds; $r++) {
    $ms = 300 + (($r * 137) % 1200)
    $p = Start-Process -FilePath $writer -ArgumentList @($db, $pw) -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err
    Start-Sleep -Milliseconds $ms
    try { Stop-Process -Id $p.Id -Force } catch {}
    $p.WaitForExit()
    $kills++
    Start-Sleep -Milliseconds 120
    $lastAck = 0
    $lines = @(Get-Content $out -ErrorAction SilentlyContinue | Where-Object { $_ -match '^\d+$' })
    if ($lines.Count -gt 0) { $lastAck = [int64]$lines[-1] }
    $res = & $writer $db $pw verify 2>&1
    $counter = -1; $vok = $false
    if ("$res" -match 'counter=(\d+) verify=(\S+)') { $counter = [int64]$matches[1]; $vok = ($matches[2] -eq 'OK') }
    if (-not $vok) { $corrupt++ }
    if ($counter -lt $lastAck) { $lost++ }
    if ($counter -lt $prevCounter) { $lost++ }
    if ($counter -gt $maxCounter) { $maxCounter = $counter }
    $prevCounter = $counter
    Write-Output ("round {0,2}: kill@{1}ms acked<={2} reopen={3} verify={4}" -f $r,$ms,$lastAck,$counter,($(if($vok){'OK'}else{'FAIL'})))
}
Write-Output "===== CRASH-DURABILITY SUMMARY ====="
Write-Output "hard kills mid-commit: $kills | final durable counter: $maxCounter"
Write-Output "corruption (verify!=OK): $corrupt | lost-acked/non-monotonic: $lost"
Write-Output ("RESULT: " + $(if ($corrupt -eq 0 -and $lost -eq 0) {'PASS - every acked commit survived every hard kill, 0 corruption'} else {'FAIL'}))

