    if (!CloseHandle(lock->handle)) {
        ok = false;
    }
    lock->handle = INVALID_HANDLE_VALUE;
    lock->held = false;
    lock->named_semaphore = false;
    return ok ? SDB_OK : SDB_E_IO;
}

